using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow for inline cases ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price with 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} but got {result}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.1, "unitPrice", DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.1, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.1, "taxRate", DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.5, "taxRate", DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData for complex/decimal-precise scenarios ---

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountValidCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithValidInputs_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> ApplyDiscountValidCases()
    {
        yield return new object[] { 100m, 0m, 100m };       // No discount
        yield return new object[] { 100m, 10m, 90m };       // 10% off
        yield return new object[] { 100m, 50m, 50m };       // Half off
        yield return new object[] { 100m, 100m, 0m };       // Full discount
        yield return new object[] { 49.99m, 25m, 37.4925m };// Fractional result
        yield return new object[] { 0m, 50m, 0m };          // Zero price
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Discount below 0 throws")]
    [DataRow(101.0, DisplayName = "Discount above 100 throws")]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRangeException(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // --- FormatPrice: DataRow for string verification ---

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "Default USD format")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "Euro symbol")]
    [DataRow(1000.5, "$", "$1000.50", DisplayName = "Pads to two decimals")]
    [DataRow(0.0, "£", "£0.00", DisplayName = "Zero in GBP")]
    public void FormatPrice_WithCurrencySymbol_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

